    'area' => 'vastral',
  ),
  1259 => 
  array (
    'member_code' => 'SSAM1253',
    'surname' => 'MORI',
    'first_name' => 'DHARMESHBHAI',
    'middle_name' => 'HARILAL',
    'email' => '',
    'phone' => '9712104591',
    'address' => 'A-302, vedant scarlett, Nr. BAPS temple, metro pillerno-135,vastral, ahmedabad.382418',
    'area' => 'vastral',
  ),
  1260 => 
  array (
    'member_code' => 'SSMA1258',
    'surname' => 'SATHWARA',
    'first_name' => 'KAMLESH BACHUBHAI SATHWARA',
    'middle_name' => 'BACHUBHAI',
    'email' => '',
