    'address' => 'D 301 Rajyash rains south vasna opposite amc water pumping station behind gb shah collage',
    'area' => 'Vasna - 382460',
  ),
);

        foreach ($records as $item) {
            $memberCode = $item['member_code'] ?: null;
            $surname = trim($item['surname']);
            $firstName = trim($item['first_name']);
            $middleName = trim($item['middle_name']);
            
            $fullName = trim(implode(' ', array_filter([$surname, $firstName, $middleName])));
            if (empty($fullName)) {
                continue;
            }

            $email = !empty($item['email']) && filter_var($item['email'], FILTER_VALIDATE_EMAIL)
                ? $item['email']
                : (strtolower($memberCode ?: 'member_' . uniqid()) . '@sathwaracommunity.org');

            $phone = !empty($item['phone']) ? preg_replace('/[^0-9]/', '', $item['phone']) : null;
            if ($phone && strlen($phone) > 10) {
                $phone = substr($phone, -10);
            }

            // Find or create area
            $areaId = null;
            if (!empty($item['area'])) {
                $cleanAreaName = trim(preg_replace('/\s*-\s*\d+$/', '', $item['area']));
                if (!empty($cleanAreaName)) {
                    $area = Area::firstOrCreate(['name' => $cleanAreaName]);
                    $areaId = $area->id;
                }
            }

            // Check if user exists by email or member_code
            $user = null;
            if ($memberCode) {
                $user = User::where('member_code', $memberCode)->first();
            }
            if (!$user && $email) {
                $user = User::where('email', $email)->first();
            }

            if (!$user) {
                $user = User::create([
                    'name' => $fullName,
                    'email' => $email,
                    'password' => Hash::make('password123'),
                    'status' => 'approved',
                    'member_code' => $memberCode,
                ]);
            } else {
                $user->update([
                    'name' => $fullName,
                    'status' => 'approved',
                    'member_code' => $memberCode ?: $user->member_code,
                ]);
            }

            $user->assignRole($memberRole);

            // Create or update member profile
            MemberProfile::updateOrCreate(
                ['user_id' => $user->id],
                [
                    'first_name' => $firstName ?: $fullName,
                    'middle_name' => $middleName,
                    'last_name' => $surname,
                    'gender' => 'Male',
                    'phone' => $phone ?: 'N/A',
                    'whatsapp' => $phone ?: 'N/A',
                    'address' => $item['address'] ?: '',
                    'area_id' => $areaId,
                    'city' => 'Ahmedabad',
                    'state' => 'Gujarat',
                ]
            );
        }

        if (isset($this->command)) {
            $this->command->info("Member import completed! Successfully seeded " . count($records) . " members.");
        }
    }
